import{_ as e,a0 as l,w as r,s as o,I as a,x as n,a1 as p,A as t,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"ArchI0：Arch Linux 应用自动安装脚本 | LCTT x X-CMD","titleTemplate":false,"description":"ArchI0：Arch Linux 应用自动安装脚本 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ArchI0：Arch Linux 应用自动安装脚本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ArchI0：Arch Linux 应用自动安装脚本 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20170721 Arch Linux Applications Automatic Installation Script","title":"ArchI0：Arch Linux 应用自动安装脚本","tag":"201808","desc":""},"relativePath":"201808/20170721 Arch Linux Applications Automatic Installation Script.md","filePath":"[post].md"}'),h={name:"201808/20170721 Arch Linux Applications Automatic Installation Script.md"};function d(u,s,g,k,A,b){const i=l("Link");return r(),o("div",null,[s[22]||(s[22]=a("h1",{id:"archi0-arch-linux-应用自动安装脚本",tabindex:"-1"},[n("ArchI0：Arch Linux 应用自动安装脚本 "),a("a",{class:"header-anchor",href:"#archi0-arch-linux-应用自动安装脚本","aria-label":"Permalink to “ArchI0：Arch Linux 应用自动安装脚本”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/07/ArchI0-Arch-Linux-Applications-Automatic-Installation-Script-720x340.png",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("Arch 用户你们好！今天，我偶然发现了一个叫做 “",-1)),s[2]||(s[2]=a("strong",null,"ArchI0",-1)),s[3]||(s[3]=n("” 的实用工具，它是基于命令行菜单的 Arch Linux 应用自动安装脚本。使用此脚本是为基于 Arch 的发行版安装所有必要的应用最简易的方式。请注意",-1)),s[4]||(s[4]=a("strong",null,"此脚本仅适用于菜鸟级使用者",-1)),s[5]||(s[5]=n("。中高级使用者可以轻松掌握",-1)),p(i,{href:"http://www.ostechnix.com/getting-started-pacman/"},{default:t(()=>[...s[0]||(s[0]=[n("如何使用 pacman",-1)])]),_:1}),s[6]||(s[6]=n("来完成这件事。如果你想学习如何使用 Arch Linux，我建议你一个个手动安装所有的软件。对那些仍是菜鸟并且希望为自己基于 Arch 的系统快速安装所有必要应用的用户，可以使用此脚本。",-1))]),s[24]||(s[24]=c(`<h3 id="archi0-–-arch-linux-应用自动安装脚本" tabindex="-1">ArchI0 – Arch Linux 应用自动安装脚本 <a class="header-anchor" href="#archi0-–-arch-linux-应用自动安装脚本" aria-label="Permalink to “ArchI0 – Arch Linux 应用自动安装脚本”">​</a></h3><p>此脚本的开发者已经制作了 <strong>ArchI0live</strong> 和 <strong>ArchI0</strong> 两个脚本。你可以通过 ArchI0live 测试应用，无需安装。这可能有助于在将脚本安装到系统之前了解其实际内容。</p><h3 id="安装-archi0" tabindex="-1">安装 ArchI0 <a class="header-anchor" href="#安装-archi0" aria-label="Permalink to “安装 ArchI0”">​</a></h3><p>要安装此脚本，使用如下命令通过 Git 克隆 ArchI0 脚本仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/SifoHamlaoui/ArchI0.git</span></span></code></pre></div><p>上面的命令会克隆 ArchI0 的 Github 仓库内容，在你当前目录的一个名为 ArchI0 的文件夹里。使用如下命令进入此目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ArchI0/</span></span></code></pre></div><p>使用如下命令赋予脚本可执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x ArchI0live.sh</span></span></code></pre></div><p>使用如下命令执行脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./ArchI0live.sh</span></span></code></pre></div><p>此脚本需要以 root 或 sudo 用户身份执行，因为安装应用需要 root 权限。</p><blockquote><p><strong>注意：</strong> 有些人想知道此脚本中开头的那些命令是做什么的，第一个命令是下载 <strong>figlet</strong>，因为此脚本的 logo 是使用 figlet 显示的。第二个命令是安装用来打开并查看许可协议文件的 <strong>Leafpad</strong>。第三个命令是安装用于从 sourceforge 下载文件的 <strong>wget</strong>。第四和第五个命令是下载许可协议文件并用 leafpad 打开。此外，最后的第 6 条命令是在阅读许可协议文件之后关闭它。</p></blockquote><p>输入你的 Arch Linux 系统架构然后按回车键。当其请求安装此脚本时，键入 <code>y</code> 然后按回车键。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/sk@sk-ArchI0_003.png" alt=""></p><p>一旦开始安装，将会重定向至主菜单。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/sk@sk-ArchI0_004-1.png" alt=""></p><p>正如前面的截图， ArchI0 包含有 13 类、90 个容易安装的程序。这 90 个程序刚好足够配置一个完整的 Arch Linux 桌面，可执行日常活动。键入 <code>a</code> 可查看关于此脚本的信息，键入 <code>q</code> 可退出此脚本。</p><p>安装后无需执行 ArchI0live 脚本。可以直接使用如下命令启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ArchI0</span></span></code></pre></div><p>它会每次询问你选择 Arch Linux 发行版的架构。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Preparing To Run Script</span></span>
<span class="line"><span> Checking For ROOT: PASSED</span></span>
<span class="line"><span> What Is Your OS Architecture? {32/64} 64</span></span></code></pre></div><p>从现在开始，你可以从主菜单列出的类别选择要安装的程序。要查看特定类别下的可用程序列表，输入类别号即可。举个例子，要查看<strong>文本编辑器</strong>分类下的可用程序列表，输入 <strong>1</strong> 然后按回车键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ R00T MENU ]</span></span>
<span class="line"><span>Make A Choice</span></span>
<span class="line"><span> 1) Text Editors</span></span>
<span class="line"><span> 2) FTP/Torrent Applications</span></span>
<span class="line"><span> 3) Download Managers</span></span>
<span class="line"><span> 4) Network managers</span></span>
<span class="line"><span> 5) VPN clients</span></span>
<span class="line"><span> 6) Chat Applications</span></span>
<span class="line"><span> 7) Image Editors</span></span>
<span class="line"><span> 8) Video editors/Record</span></span>
<span class="line"><span> 9) Archive Handlers</span></span>
<span class="line"><span> 10) Audio Applications</span></span>
<span class="line"><span> 11) Other Applications</span></span>
<span class="line"><span> 12) Development Environments</span></span>
<span class="line"><span> 13) Browser/Web Plugins</span></span>
<span class="line"><span> 14) Dotfiles</span></span>
<span class="line"><span> 15) Usefull Links</span></span>
<span class="line"><span> ------------------------</span></span>
<span class="line"><span> a) About ArchI0 Script</span></span>
<span class="line"><span> q) Leave ArchI0 Script</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose An Option: 1</span></span></code></pre></div><p>接下来，选择你想安装的程序。要返回至主菜单，输入 <code>q</code> 然后按回车键。</p><p>我想安装 Emacs，所以我输入 <code>3</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>This script Is under GPLv3 License</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[ TEXT EDITORS ]</span></span>
<span class="line"><span> [ Option ] [ Description ]</span></span>
<span class="line"><span> 1) GEdit</span></span>
<span class="line"><span> 2) Geany</span></span>
<span class="line"><span> 3) Emacs</span></span>
<span class="line"><span> 4) VIM</span></span>
<span class="line"><span> 5) Kate</span></span>
<span class="line"><span> ---------------------------</span></span>
<span class="line"><span> q) Return To Main Menu</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Choose An Option: 3</span></span></code></pre></div><p>现在，Emacs 将会安装至你的 Arch Linux 系统。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/07/pacman-as-superuser_005.png" alt=""></p><p>所选择的应用安装完成后，你可以按回车键返回主菜单。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>毫无疑问，此脚本让 Arch Linux 用户使用起来更加容易，特别是刚开始使用的人。如果你正寻找快速简单无需使用 pacman 安装应用的方法，此脚本是一个不错的选择。试用一下并在下面的评论区让我们知道你对此脚本的看法。</p><p>就这些。希望这个工具能帮到你。我们每天都会推送实用的指南。如果你觉得我们的指南挺实用，请分享至你的社交网络，专业圈子并支持我们。</p><p>干杯！</p><hr>`,35)),a("p",null,[s[8]||(s[8]=n("via: ",-1)),p(i,{href:"https://www.ostechnix.com/archi0-arch-linux-applications-automatic-installation-script/"},{default:t(()=>[...s[7]||(s[7]=[n("https://www.ostechnix.com/archi0-arch-linux-applications-automatic-installation-script/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=n("作者：",-1)),p(i,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[9]||(s[9]=[n("SK",-1)])]),_:1}),s[14]||(s[14]=n(" 选题：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[10]||(s[10]=[n("lujun9972",-1)])]),_:1}),s[15]||(s[15]=n(" 译者：",-1)),p(i,{href:"https://github.com/fuowang"},{default:t(()=>[...s[11]||(s[11]=[n("fuowang",-1)])]),_:1}),s[16]||(s[16]=n(" 校对：",-1)),p(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原创编译，",-1)),p(i,{href:"https://linux.cn/"},{default:t(()=>[...s[18]||(s[18]=[n("Linux中国",-1)])]),_:1}),s[21]||(s[21]=n(" 荣誉推出",-1))])])}const I=e(h,[["render",d]]);export{x as __pageData,I as default};
